INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(30711, 'Luke 10:7', 'Luke', 10, 7, 'په هماغه کور کې پاتې شئ او هغوی چې هرڅه درکوي ویې خورئ او ویې وڅښئ، ځکه چې مزدور د خپلې مزدورۍ حقدار دی. کور په کور مه ګرځئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_7.mp3', '', 1761754199, 1761754199),
(30712, 'Luke 10:8', 'Luke', 10, 8, 'کله چې تاسو کوم ښار ته ننوځئ او هغوی درته هرکلی ووایي، نو څه چې یې ستاسو په مخکې کېښودل هغه وخورئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_8.mp3', '', 1761754199, 1761754199),
(30713, 'Luke 10:9', 'Luke', 10, 9, 'د هغه ځای ناروغان روغ کړئ او خلکو ته ووایئ چې د خدای پاچاهي تاسو ته نژدې شوې ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_9.mp3', '', 1761754199, 1761754199),
(30714, 'Luke 10:10', 'Luke', 10, 10, 'خو کله چې تاسو کوم ښار ته ورننوځئ او هغوی درته هرکلی ونه وایي، نو د هغه ښار کوڅو ته ووځئ او ووایئ:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_10.mp3', '', 1761754199, 1761754199),
(30715, 'Luke 10:11', 'Luke', 10, 11, '‹مونږ به ستاسو د ښار خاورې هم چې زمونږ په پښو باندې پرېوتې دي وڅنډو او دا به ستاسو په خلاف شاهدي ورکوي. خو په دې پوه شئ چې د خدای پاچاهي نژدې شوې ده.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_11.mp3', '', 1761754199, 1761754199),
(30716, 'Luke 10:12', 'Luke', 10, 12, 'زه تاسو ته وایم چې د قیامت په ورځ به د سدوم د خلکو سزا د دې ښار د خلکو د سزا څخه کمه وي. هغه ښارونه چې خلک یې توبه نه وباسي (متي ۱۱‏:‌۲۰‌‏-‌۲۴)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_12.mp3', '', 1761754199, 1761754199),
(30717, 'Luke 10:13', 'Luke', 10, 13, 'افسوس دې وي په تا ای د خورزین ښاره! افسوس دې وي په تا ای د بیت‌صیدا ښاره! ځکه که چېرې دا معجزې چې په تاسو کې وښودل شوې، که هغه په صور او صیدون کې ښودل شوې وای نو هغوی به ډېر پخوا د ویر کالي اغوستي وای، په خپلو سرونو باندې به یې ایرې بادولې او توبه به یې ویستلې وای.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_13.mp3', '', 1761754199, 1761754199),
(30718, 'Luke 10:14', 'Luke', 10, 14, 'خو د قیامت په ورځ به د صیدون او صور د خلکو سزا ستاسو د سزا څخه کمه وي‎.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_14.mp3', '', 1761754199, 1761754199),
(30719, 'Luke 10:15', 'Luke', 10, 15, 'خو ای کپرناحومه! تا غوښتل چې اسمان ته پورته کړای شې؟ خو ته به دوزخ ته وغورځول شې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_15.mp3', '', 1761754199, 1761754199),
(30720, 'Luke 10:16', 'Luke', 10, 16, 'عیسی خپلو شاګردانو ته وویل: «څوک چې ستاسو خبرو ته غوږ نیسي، هغوی زما خبرو ته غوږ نیسي. څوک چې تاسې نه مني، هغوی ما نه مني او څوک چې ما نه مني نو هغه څوک نه مني چې زه یې رالېږلی یم.» د دوه اویا شاګردانو بېرته راستنېدل', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_16.mp3', '', 1761754199, 1761754199),
(30721, 'Luke 10:17', 'Luke', 10, 17, 'بیا هغه دوه اویا شاګردان په خوشحالۍ سره بېرته راستانه شول او ویې ویل: «استاذه! حتی پېریان هم ستا د نوم په یادولو سره زمونږ تابع کیږي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_17.mp3', '', 1761754199, 1761754199),
(30722, 'Luke 10:18', 'Luke', 10, 18, 'عیسی هغوی ته په ځواب کې وویل: «ما ولیدل چې شیطان څنګه لکه د برېښنا په شان له اسمانه راوغورځېد.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_18.mp3', '', 1761754199, 1761754199),
(30723, 'Luke 10:19', 'Luke', 10, 19, 'واورئ! ما تاسو ته واک او اختیار درکړی چې ماران او لړمان تر‌پښو لاندې کړئ او د دښمن ټول قوت مات کړئ. هېڅ شی تاسو ته زیان نه شي رسولی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_19.mp3', '', 1761754199, 1761754199),
(30724, 'Luke 10:20', 'Luke', 10, 20, 'خو په دې مه خوشحالېږئ چې پېریان تاسو ته تابع کیږي، بلکې په دې خوشحاله اوسئ چې ستاسو نومونه په جنت کې لیکل شوي دي.» د عیسی خوشحالي (متي ۱۱‏:‌۲۵‌‏-‌۲۷، ۱۳‏:‌۱۶‌‏-‌۱۷)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_20.mp3', '', 1761754199, 1761754199),
(30725, 'Luke 10:21', 'Luke', 10, 21, 'په هغه وخت کې عیسی په روح القدس کې خوشحالي وکړه او ویې ویل: «ای پلاره، ای د ځمکې او اسمان څښتنه! زه ستا شکر کوم چې دا خبرې دې د پوهو او هوښیارو خلکو څخه پټې کړې او ناپوهو خلکو ته دې ښکاره کړي دي. هو پلاره، دا ستا رضا وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_21.mp3', '', 1761754199, 1761754199),
(30726, 'Luke 10:22', 'Luke', 10, 22, 'زما پلار هرڅه ماته راسپارلي دي. هېڅوک له پلاره پرته زوی نه پېژني او نه څوک پلار بې له زویه پېژني او پرته له هغه چا چې زوی وغواړي ورته ویې ښایي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_22.mp3', '', 1761754199, 1761754199),
(30727, 'Luke 10:23', 'Luke', 10, 23, 'کله چې هغوی یوازې وو، نو عیسی هغوی ته مخ راواړاوه او ورته ویې ویل: «بختورې دي هغه سترګې چې هغه څه ویني چې تاسو یې وینئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_23.mp3', '', 1761754199, 1761754199),
(30728, 'Luke 10:24', 'Luke', 10, 24, 'زه تاسو ته وایم چې ډېرو پیغمبرانو او پاچاهانو دا ارمان درلود چې هغه څه وویني چې تاسو یې وینئ، خو ویې نه لیدل او هغه څه واوري چې تاسو یې اورئ، خو هغوی وانه ورېدل.» د یو نېک سامري مثال', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_24.mp3', '', 1761754199, 1761754199),
(30729, 'Luke 10:25', 'Luke', 10, 25, 'یوه ورځ د شریعت یو عالم راغی او د عیسی څخه یې د ازمېښت دپاره یو سوال وکړ: «استاذه! زه باید څه وکړم چې تلپاتې ژوندون وګټم؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_25.mp3', '', 1761754199, 1761754199),
(30730, 'Luke 10:26', 'Luke', 10, 26, 'عیسی هغه ته ځواب ورکړ: «په شریعت کې څه لیکل شوي دي؟ هغه څنګه تعبیروې؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_26.mp3', '', 1761754199, 1761754199),
(30731, 'Luke 10:27', 'Luke', 10, 27, 'هغه په ځواب کې وویل: «د خپل څښتن خدای سره د زړه له کومي، په خپل ټول روح او خپل ټول قوت او ټول عقل سره مینه کوه او د خپل ګاونډي سره د خپل ځان په شان مینه کوه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_27.mp3', '', 1761754199, 1761754199),
(30732, 'Luke 10:28', 'Luke', 10, 28, 'عیسی ورته وویل: «تا سم ځواب ورکړ. همداسې کوه، نو ته به ژوندی اوسې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_28.mp3', '', 1761754199, 1761754199),
(30733, 'Luke 10:29', 'Luke', 10, 29, 'خو د دې دپاره چې د شریعت عالم دا وښایي چې هغه په حقه دی، نو د عیسی څخه یې پوښتنه وکړه: «زما ګاونډی څوک دی؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_29.mp3', '', 1761754199, 1761754199),
(30734, 'Luke 10:30', 'Luke', 10, 30, 'عیسی داسې ځواب ورکړ: «په یو وخت کې یو سړی د اورشلیم څخه اریحا ته روان ؤ چې په لاره کې داړه مارانو ته په لاس ورغی. غلو هغه سړی لوڅ کړ، ویې واهه او د مرګ په حالت کې یې پرېښود او لاړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_30.mp3', '', 1761754199, 1761754199),
(30735, 'Luke 10:31', 'Luke', 10, 31, 'ناڅاپه یو کاهن په هغه لاره تېرېده، کله یې چې هغه سړی ولیده، نو خپله لاره یې پرېښوده او ورڅخه تېر شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_31.mp3', '', 1761754199, 1761754199),
(30736, 'Luke 10:32', 'Luke', 10, 32, 'همدارنګه یو لاوي چې کله هغه ځای ته راورسېد او هغه سړی یې ولیده، نو هغه هم ترې په بله خوا تېر شو او لاړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_32.mp3', '', 1761754199, 1761754199),
(30737, 'Luke 10:33', 'Luke', 10, 33, 'خو یو سامری چې په هغه لاره تېرېده هغه ته ورغی او کله یې چې هغه سړی ولیده نو زړه یې ورباندې وسوځېد.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_33.mp3', '', 1761754199, 1761754199),
(30738, 'Luke 10:34', 'Luke', 10, 34, 'هغه ته ورغی، ټپونه یې ورته په شرابو ووینځل او تېل یې ورباندې واچول او پټۍ یې ورباندې کېښودله. بیا یې هغه په خپل خره باندې سپور کړ او یوې مسافرخانې ته یې یووړ او هلته یې ورباندې پام کاوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_34.mp3', '', 1761754199, 1761754199),
(30739, 'Luke 10:35', 'Luke', 10, 35, 'سبا سهار هغه د سپینو زرو دوه سکې واخیستې او د مسافرخانې خاوند ته یې ورکړې او ورته ویې ویل: ‹په هغه باندې پام کوه او که نورې پیسې دې ورباندې ولګولې نو کله چې بېرته راغلم هغه به هم درکړم.›»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_35.mp3', '', 1761754199, 1761754199),
(30740, 'Luke 10:36', 'Luke', 10, 36, 'بیا عیسی پوښتنه وکړه: «اوس څه فکر کوې چې په دې درې واړو کې د هغه سړي چې د داړه مارانو لاس ته ورغلی ؤ، ګاونډی څوک دی؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_36.mp3', '', 1761754199, 1761754199),
(30741, 'Luke 10:37', 'Luke', 10, 37, 'د شریعت عالم ځواب ورکړ: «هغه څوک چې په هغه باندې یې رحم وکړ.» عیسی ورته وویل: «لاړ شه او ته هم همداسې کوه.» عیسی د مرتا او مریم سره لیدنه کوي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_37.mp3', '', 1761754199, 1761754199),
(30742, 'Luke 10:38', 'Luke', 10, 38, 'کله چې عیسی او شاګردان یې په خپله لاره روان شول، هغوی یو کلي ته ورسېدل او هلته یوې ښځې چې مرتا نومېدله عیسی په خپل کور کې مېلمه کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_38.mp3', '', 1761754199, 1761754199),
(30743, 'Luke 10:39', 'Luke', 10, 39, 'هغې د مریم په نوم یوه خور درلودله. هغه راغله او د عیسی پښو ته کښېناستله او د هغه خبرو ته یې غوږ نیولی ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_39.mp3', '', 1761754199, 1761754199),
(30744, 'Luke 10:40', 'Luke', 10, 40, 'مرتا د ډېرو کارونو له لاسه ستړې او پرېشانه شوه، نو عیسی ته راغله او ورته ویې ویل: «استاذه! ستا دې ته پام نه دی چې ټول کارونه زه کوم او خور مې راسره مرسته نه کوي؟ هغې ته ووایه چې راشي او مرسته راسره وکړي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_40.mp3', '', 1761754199, 1761754199),
(30745, 'Luke 10:41', 'Luke', 10, 41, 'عیسی هغې ته په ځواب کې وویل: «مرتا، مرتا! ته د ډېرو شیانو دپاره اندېښنه کوې او نا‌ارامه یې،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_41.mp3', '', 1761754199, 1761754199),
(30746, 'Luke 10:42', 'Luke', 10, 42, 'خو یوازې یو شی ضروري دی. څه چې مریم خوښ کړي دي هغه ښه دي او دا به له هغې څخه وانخیستل شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke10_verse_42.mp3', '', 1761754199, 1761754199),
(30747, 'Matthew 19:1', 'Matthew', 19, 1, 'کله چې عیسی دا خبرې خلاصې کړې، نو د جلیل څخه روان شو او د یهودیې سیمې ته چې د اردن د سیند په بله غاړه پرته وه لاړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew19_verse_1.mp3', '', 1761754199, 1761754199),
(30748, 'Matthew 19:2', 'Matthew', 19, 2, 'ګڼ شمېر خلک ورپسې روان وو او عیسی هلته هغوی ته شفا ورکړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew19_verse_2.mp3', '', 1761754199, 1761754199),
(30749, 'Matthew 19:3', 'Matthew', 19, 3, 'ځینې فریسیان هغه ته راغلل او د دې دپاره چې هغه وازمایي، نو پوښتنه یې ترې وکړه: «ایا دا روا ده چې یو سړی دې خپله ښځه چې په هر دلیل وي طلاقه کړي؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew19_verse_3.mp3', '', 1761754199, 1761754199),
(30750, 'Matthew 19:4', 'Matthew', 19, 4, 'عیسی په ځواب کې وویل: «ایا تاسو نه دي لوستلي چې په پیل کې چې کله خالق انسانان پیدا کړل، نو هغه یې نر او ښځه پیدا کړل؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew19_verse_4.mp3', '', 1761754199, 1761754199),
(30751, 'Matthew 19:5', 'Matthew', 19, 5, 'او خدای وویل: نو له همدې امله سړی خپل مور او پلار پرېږدي او د خپلې ښځې سره یوځای کیږي او دواړه یو بدن شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew19_verse_5.mp3', '', 1761754199, 1761754199),
(30752, 'Matthew 19:6', 'Matthew', 19, 6, 'نو هغوی نور دوه تنه نه بلکې یو تن وي. نو څرنګه چې خدای هغوی سره یوځای کړي دي، انسان باید هغوی سره بېل نه کړي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew19_verse_6.mp3', '', 1761754199, 1761754199),
(30753, 'Matthew 19:7', 'Matthew', 19, 7, 'فریسیانو د عیسی نه پوښتنه وکړه: «نو بیا موسی په دې هکله ولې حکم کړی دی چې یو سړی کولای شي خپلې ښځې ته طلاق‌نامه ورکړي او هغه وشړي؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew19_verse_7.mp3', '', 1761754199, 1761754199),
(30754, 'Matthew 19:8', 'Matthew', 19, 8, 'عیسی ځواب ورکړ: «موسی تاسو ته د دې دپاره اجازه درکړه چې خپلو ښځو ته طلاق ورکړئ، ځکه چې ستاسو زړونه سخت وو. خو د پیدایښت له وخته داسې نه ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew19_verse_8.mp3', '', 1761754199, 1761754199),
(30755, 'Matthew 19:9', 'Matthew', 19, 9, 'زه تاسو ته وایم چې که څوک خپله ښځه ‎له زنا کولو پرته په کوم بل دلیل طلاقه کړي او د بلې ښځې سره واده وکړي، نو هغه زنا کوي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew19_verse_9.mp3', '', 1761754199, 1761754199),
