(30779, 'Romans 15:3', 'Romans', 15, 3, 'ځکه چې مسیح هم کوښښ ونه کړ چې خپل ځان خوشحاله کړي. خو لکه څنګه چې د خدای په کلام کې لیکل شوي دي: «کومو خلکو چې ستاسو سپکاوی وکړ، هغوی زما سپکاوی هم وکړ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans15_verse_3.mp3', '', 1761754199, 1761754199),
(30780, 'Romans 15:4', 'Romans', 15, 4, 'ځکه هرڅه چې پخوا لیکل شوي دي، هغه زمونږ د لارښوونې دپاره لیکل شوي دي ترڅو مونږ د صبر او هغې تسلۍ په وسیله چې د خدای کلام یې مونږ ته راکوي، هیله مند واوسو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans15_verse_4.mp3', '', 1761754199, 1761754199),
