(30795, 'Romans 15:19', 'Romans', 15, 19, 'د نښو او حیرانوونکو کارونو په قدرت او د خدای د روح په قدرت سره هغوی قانع شول، ځکه چې ما د اورشلیم نه تر ایلیریکوم پورې په ټوله لاره د مسیح زېری په پوره توګه ورساوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans15_verse_19.mp3', '', 1761754199, 1761754199),
(30796, 'Romans 15:20', 'Romans', 15, 20, 'دا زما مقصد ؤ چې زېری هغو ځایونو ته ورسوم چې تر‌اوسه یې د مسیح نوم نه دی اورېدلی، ترڅو زه په هغه بنیاد باندې داسې کوم څه جوړ نه کړم چې بل چا ایښی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans15_verse_20.mp3', '', 1761754199, 1761754199),
(30797, 'Romans 15:21', 'Romans', 15, 21, 'بلکې لکه څنګه چې د خدای په کلام کې لیکل شوي دي: چاته چې د هغه په هکله څه نه دي ویل شوي، هغوی به یې وویني او چا چې د هغه په هکله څه نه دي اورېدلي هغوی به پوه شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans15_verse_21.mp3', '', 1761754199, 1761754199),
(30798, 'Romans 15:22', 'Romans', 15, 22, 'له همدې امله څو څو ځلې تاسو ته زما د راتللو مخنیوی وشو. روم ته د پولوس د تګ مقصد', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans15_verse_22.mp3', '', 1761754199, 1761754199),
(30799, 'Romans 15:23', 'Romans', 15, 23, 'خو اوس چې ما خپل کار په دې سیمو کې پای ته رسولی دی او کلونه کلونه کیږي چې زه په دې ارمان وم چې راشم او تاسو ووینم،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans15_verse_23.mp3', '', 1761754199, 1761754199),
(30800, 'Romans 15:24', 'Romans', 15, 24, 'نو زه په دې هیله یم چې اسپانیې ته د سفر په وخت کې تاسو سره د لږ وخت دپاره ووینم او کله مې چې ستاسو سره لیدنه وکړه، نو بیا به ستاسو په مرسته خپل سفر ته دوام ورکړم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans15_verse_24.mp3', '', 1761754199, 1761754199),
(30801, 'Romans 15:25', 'Romans', 15, 25, 'خو اوس د خدای د خلکو سره د مرستې په خاطر اورشلیم ته ځم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans15_verse_25.mp3', '', 1761754199, 1761754199),
(30802, 'Romans 15:26', 'Romans', 15, 26, 'ځکه چې د مقدونیې او جنوبي یونان ایماندارانو د زړه له اخلاصه پرېکړه کړې ده چې په اورشلیم کې غریبو ایماندارانو ته یو څه پیسې د مالي مرستې په توګه ورکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans15_verse_26.mp3', '', 1761754199, 1761754199),
(30803, 'Romans 15:27', 'Romans', 15, 27, 'هغوی خوشحاله وو چې دا کار وکړي او په حقیقت کې هغوی خپل ځانونه د یهودیانو پوروړي ګڼل. څرنګه چې یهودیانو خپل روحاني برکتونه د غیریهودیانو سره شریک کړل، نو غیریهودیان باید د دې په بدل کې د هغوی سره مالي مرستې وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans15_verse_27.mp3', '', 1761754199, 1761754199),
(30804, 'Romans 15:28', 'Romans', 15, 28, 'نو کله چې زه دا کار سرته ورسوم او هغه پیسې چې راټولې شوې دي هغوی ته وسپارم، نو بیا زه اسپانیې ته ځم او په لاره کې به ستاسو سره لیدنه وکړم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans15_verse_28.mp3', '', 1761754199, 1761754199),
(30805, 'Romans 15:29', 'Romans', 15, 29, 'زه پوهېږم چې کله تاسو ته درځم، نو د مسیح د پوره برکتونو سره به درځم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans15_verse_29.mp3', '', 1761754199, 1761754199),
(30806, 'Romans 15:30', 'Romans', 15, 30, 'ای خویندو او ورونو! زه ستاسو نه د خپل څښتن عیسی مسیح او هغې مینې په خاطر چې روح القدس یې تاسو ته درکوي، غوښتنه کوم چې زما سره په هلوځلو کې خدای ته په دعا کولو سره یوځای شئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans15_verse_30.mp3', '', 1761754199, 1761754199),
