(30808, 'Romans 15:32', 'Romans', 15, 32, 'نو که د خدای رضا وي، په خوشحالۍ به تاسو ته درشم او ستاسو په ملګرتیا او لیدنې سره به بېرته تکړه شم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans15_verse_32.mp3', '', 1761754199, 1761754199),
(30809, 'Romans 15:33', 'Romans', 15, 33, 'خدای چې د سولې او سلامتۍ سرچینه ده، هغه دې تاسو ټولو سره وي. امین.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans15_verse_33.mp3', '', 1761754199, 1761754199),
(30810, 'James 2:1', 'James', 2, 1, 'ای زما خویندو او ورونو! که چېرې تاسو زمونږ په څښتن عیسی مسیح چې د جلال خاوند دی ایمان لرئ، نو د چا طرفداري مه کوئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james2_verse_1.mp3', '', 1761754199, 1761754199);